### 参考答案

**1. 匿名内部类（非静态）可以访问外部类的实例引用**  
**为什么**：  
非静态匿名内部类隐式持有外部类的实例引用（`Outer.this`），因此可以直接访问外部类的**实例成员**（包括私有字段和方法）。这是Java内部类的核心特性之一，用于实现事件监听、回调等场景。  

**怎么做**：  
在匿名内部类中直接访问外部类的实例变量或方法，无需显式声明外部类引用。例如：  
```java
public class Outer {
    private String name = "Outer";
    public void createInner() {
        Runnable r = new Runnable() {
            public void run() {
                System.out.println(name); // 直接访问外部类实例变量
            }
        };
    }
}
```

---

**2. 静态匿名内部类不能访问外部类的实例引用**  
**为什么**：  
静态匿名内部类不持有外部类的实例引用，仅能访问外部类的**静态成员**。这是静态内部类的语义限制，与静态方法只能访问静态变量的原理一致。  

**怎么做**：  
静态匿名内部类只能使用外部类的静态变量或方法，否则会编译报错。例如：  
```java
public class Outer {
    private static String staticName = "StaticOuter";
    public static void createStaticInner() {
        Runnable r = new Runnable() {
            public void run() {
                System.out.println(staticName); // 正确：访问静态变量
                // System.out.println(name); // 编译错误：name是实例变量
            }
        };
    }
}
```

---

**关键对比总结**  
| 类型                | 是否持有外部类引用 | 可访问的外部类成员       | 典型场景               |  
|---------------------|---------------------|--------------------------|------------------------|  
| 非静态匿名内部类    | ✅ 隐式持有         | 实例成员 + 静态成员      | 事件监听、回调         |  
| 静态匿名内部类      | ❌ 不持有           | 仅静态成员               | 工具类、与外部类解耦   |  

**注意事项**：  
- 若需静态匿名内部类访问外部类实例，需显式传入外部类对象（如构造函数参数）。  
- 匿名内部类无法定义构造函数，但可通过初始化块或实例变量赋值模拟。  

**ASCII调用关系示例**：  
```
Outer实例 -> 非静态匿名内部类（持有Outer.this引用）  
Outer类   -> 静态匿名内部类（仅依赖Outer类静态成员）
```'),
