### 参考答案：

**1. 定义与结构差异**  
- **静态内部类**：使用 `static` 修饰，属于外部类的静态成员，无需依赖外部类实例即可创建。  
  ```java
  class Outer {
      static class Inner { // 静态内部类
          void show() { System.out.println("Inner"); }
      }
  }
  ```
  **为什么**：静态内部类与外部类解耦，适合工具类或独立功能模块。  
  **怎么做**：通过 `Outer.Inner obj = new Outer.Inner();` 直接实例化。

- **匿名内部类**：无类名，继承类或实现接口的临时子类，语法上直接嵌入表达式中。  
  ```java
  Runnable r = new Runnable() { // 匿名内部类
      public void run() { System.out.println("Anonymous"); }
  };
  ```
  **为什么**：简化一次性接口/抽象类的实现，避免冗余类定义。  
  **怎么做**：在需要实现接口或继承抽象类的位置直接定义类体。

---

**2. 访问权限与依赖关系**  
- **静态内部类**：只能访问外部类的静态成员，需通过外部类实例访问非静态成员。  
  ```java
  class Outer {
      private static int x = 10;
      static class Inner {
          void print() { System.out.println(x); } // 直接访问静态变量
      }
  }
  ```
  **为什么**：静态上下文无法关联外部类实例，因此仅能操作静态资源。  

- **匿名内部类**：可访问外部类的所有成员（包括私有），但必须为 `final` 或有效 `final`。  
  ```java
  class Outer {
      private int y = 20;
      void method() {
          Runnable r = () -> System.out.println(y); // 捕获外部变量
      }
  }
  ```
  **为什么**：匿名类本质是外部类方法内的局部类，需保证捕获变量的线程安全。

---

**3. 使用场景对比**  
- **静态内部类**：适用于与外部类强关联但独立的场景（如 `ArrayList.Itr` 迭代器）。  
  ```java
  // 示例：链表节点作为静态内部类
  class LinkedList {
      static class Node { int val; Node next; }
  }
  ```
- **匿名内部类**：多用于事件监听、线程任务等临时实现（如 Swing 按钮点击）。  
  ```java
  button.addActionListener(e -> System.out.println("Clicked")); // 等价于匿名类
  ```

---

**4. 内存与生命周期**  
- 静态内部类实例与外部类解耦，GC 独立回收；匿名内部类随外部对象生命周期结束而失效。  
  **线框图**：  
  ```
  Outer -> StaticInner (独立存在)
  Outer -> AnonymousInner (依附于 Outer 实例)
  ```

---

**总结**：静态内部类强调模块化和复用性，匿名内部类追求代码简洁性。选择依据是功能是否需要长期存在或临时实现。'),
