**怎么做**：我边读边复现核心算法。例如用NumPy从零实现SVM的SMO算法，对比sklearn的LinearSVC，发现核函数选择对非线性数据的影响显著。书中第7章的AdaBoost推导让我重新审视了集成学习的偏差-方差权衡，最近在优化推荐模型时，用类似思想调整了多模型加权策略，AUC提升了3%。

**2. 《Hands-On Machine Learning》——强化工程落地**  
