**怎么做**：我会用Anki整理公式和代码片段，同时写博客总结（如《SVM的几何解释》）。最近在读《Deep Learning》第6章时，发现其正则化理论与《统计学习方法》第6章的泛化误差分析相通，这种跨书关联加深了理解。

这两本书形成“理论+实践”闭环，既巩固了算法根基，又提升了工程能力，与算法岗的需求高度匹配。'),
