- **分布式锁**：用Redisson实现可重入锁，解决库存扣减的并发冲突问题。  
- **链路追踪**：集成Zipkin监控微服务调用链，快速定位超时节点。  

#### 3. **团队协作与角色**  
**为什么**：竞赛需高效协作，明确分工是成功关键。  
