- **反思**：初期未考虑缓存雪崩问题，后通过随机过期时间策略解决，体会到“防御性编程”的重要性。

---

**总结**：实习让我从“能写代码”进阶到“能解决复杂问题”，未来希望深入高可用架构设计，持续为团队创造价值。  

