### LRU缓存实现参考答案  

**1. 核心原理与数据结构选择**  
- **为什么用哈希表+双向链表？**  
  LRU需要快速定位元素（O(1)查找）并维护访问顺序。哈希表存储键值对和链表节点引用，双向链表按访问时间排序，头节点为最新，尾节点为最旧。  
  ```java
  class Node {
      int key, value;
      Node prev, next;
      Node(int k, int v) { key = k; value = v; }
  }
  ```

**2. 关键操作实现**  
- **get()方法**  
  - **为什么移动节点？** 访问后需更新为最新。  
  - **怎么做？** 若键存在，将对应节点移至链表头部，返回value；否则返回-1。  
  ```java
  public int get(int key) {
      if (map.containsKey(key)) {
          Node node = map.get(key);
          remove(node); // 从原位置删除
          addToHead(node); // 插入头部
          return node.value;
      }
      return -1;
  }
  ```

- **put()方法**  
  - **为什么淘汰尾部节点？** 超出容量时删除最久未使用的元素。  
  - **怎么做？** 若键存在则更新值并移动；否则创建新节点插入头部，若超容量则删除尾节点。  
  ```java
  public void put(int key, int value) {
      if (map.containsKey(key)) {
          Node node = map.get(key);
          node.value = value;
          remove(node);
          addToHead(node);
      } else {
          Node node = new Node(key, value);
          map.put(key, node);
          addToHead(node);
          if (map.size() > capacity) {
              Node tail = removeTail();
              map.remove(tail.key);
          }
      }
  }
  ```

**3. 辅助操作与复杂度**  
- **链表操作**：`addToHead()`/`removeTail()`通过修改指针实现O(1)操作。  
- **时间复杂度**：get/put均为O(1)，哈希表+链表双结构保证高效。  
- **空间复杂度**：O(N)，N为缓存容量。  

**4. 实际场景优化**  
- **线程安全**：生产环境需加锁或使用`ConcurrentHashMap`+`ReentrantLock`。  
- **Java内置实现**：`LinkedHashMap`通过重写`removeEldestEntry()`可快速实现LRU。  

**架构示意**  
```
Cache
|-> HashMap: key -> Node
|-> DoublyLinkedList: head <-> [Node1] <-> [Node2] <-> tail
```  
**总结**：通过哈希表加速查找、双向链表维护顺序，实现O(1)的LRU策略，适用于高频访问场景（如数据库缓存、CDN）。'),
  ('other-399', '

### 参考答案  

**1. 整体思路**  
- **为什么分组反转？**  
  题目要求每K个节点为一组反转，若剩余不足K个则保持原样。直接全量反转会破坏分组规则，因此需分段处理。  
- **怎么做？**  
  通过遍历链表，每次截取K个节点进行局部反转，再将反转后的子链表与前一段连接。例如：  
  ```
  原链表: 1->2->3->4->5->6->7 (K=3)  
  分组: [1,2,3] [4,5,6] [7]  
  反转后: 3->2->1->6->5->4->7  
  ```

**2. 关键步骤**  
- **步骤1：判断剩余节点是否足够K个**  
  - **为什么？** 避免最后不足K的节点被错误反转。  
  - **怎么做？** 用临时指针遍历K个节点，若中途遇到`null`则直接返回原链表。  
    ```java
    // 检查剩余节点数
    Node temp = head;
    for (int i = 0; i < K; i++) {
        if (temp == null) return head; // 不足K个，终止
        temp = temp.next;
    }
    ```

- **步骤2：反转K个节点**  
  - **为什么用迭代法？** 递归可能导致栈溢出，迭代更稳定且空间复杂度O(1)。  
  - **怎么做？** 用三指针（`prev`, `curr`, `next`）逐步反转：  
    ```java
    Node prev = null, curr = head, next;
    for (int i = 0; i < K; i++) {
        next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    ```

- **步骤3：递归处理剩余部分并连接**  
  - **为什么递归？** 简化后续节点的处理逻辑，避免手动维护多段链表。  
  - **怎么做？** 将当前段的尾节点（原`head`）连接到下一组的头节点：  
    ```java
    head.next = reverseKGroup(curr, K); // 递归处理剩余部分
    return prev; // 返回反转后的新头节点
    ```

**3. 复杂度与边界处理**  
- **时间复杂度**：O(N)，每个节点最多被访问两次（检查+反转）。  
- **空间复杂度**：O(1)（迭代）或O(N/K)（递归栈）。  
- **边界案例**：K=1时直接返回原链表；链表长度< K时保持原样。  

**4. 实际场景优化**  
若链表极长，可改用迭代法避免递归栈溢出。例如，用`dummy`节点统一处理头节点变化：  
```
dummy -> [1,2,3] -> [4,5,6] -> [7]  
dummy.next = 反转后[3,2,1] -> 反转后[6,5,4] -> [7]  
```  

**总结**：通过分段检查、局部反转和递归连接，确保逻辑严谨且高效。代码需重点测试K=1、链表长度< K等边界条件。'),
