### 参考答案：无重复字符最长子串（滑动窗口）

**1. 问题理解**  
题目要求找到字符串中不含重复字符的最长子串长度。核心难点在于动态维护一个“无重复”的窗口，并高效更新其边界。滑动窗口法适合此场景，因其能通过双指针动态调整区间，避免暴力枚举所有子串（时间复杂度O(n²)）。

**2. 解题思路**  
- **为什么用滑动窗口？**  
  重复字符会破坏窗口合法性，需动态收缩左边界。滑动窗口通过记录字符位置，可O(1)判断重复并调整边界。  
- **怎么做？**  
  1. 初始化左右指针`left=0`，哈希表`charIndex`存储字符最新位置，`maxLen=0`。  
  2. 右指针`right`遍历字符串：  
     - 若当前字符`c`已存在且位置≥`left`，说明重复，将`left`移至`charIndex[c]+1`。  
     - 更新`charIndex[c]=right`，计算当前窗口长度`right-left+1`，更新`maxLen`。  

**3. 代码示例**  
```java
public int lengthOfLongestSubstring(String s) {
    Map<Character, Integer> charIndex = new HashMap<>();
    int left = 0, maxLen = 0;
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (charIndex.containsKey(c) && charIndex.get(c) >= left) {
            left = charIndex.get(c) + 1; // 收缩左边界
        }
        charIndex.put(c, right);
        maxLen = Math.max(maxLen, right - left + 1);
    }
    return maxLen;
}
```

**4. 关键点说明**  
- **哈希表作用**：记录字符最新位置，快速定位重复字符。  
- **边界处理**：`charIndex.get(c) >= left`确保只处理当前窗口内的重复（如"abba"中第二个''b''需跳过第一个''b''）。  
- **时间复杂度**：O(n)，每个字符最多被左右指针各访问一次。  

**5. 实际场景延伸**  
在日志分析中，可优化为统计无重复操作序列的最长长度，帮助识别用户行为模式。例如，用户操作序列`"click,scroll,click"`的最长无重复子串为`"click,scroll"`。  

**ASCII流程示意**  
```
输入: "abcabcbb"  
滑动窗口变化：  
[abc] -> [bca] -> [cab] -> [abc] -> [b]  
maxLen = 3（"abc"）
```'),
