### 二叉树层序遍历与右视图参考答案

**1. 核心思路**  
- **为什么用层序遍历？**  
  层序遍历天然按层级处理节点，适合获取每层最右侧节点（右视图本质是每层最后一个节点）。  
- **怎么做？**  
  使用队列实现BFS，逐层遍历并记录每层最后一个节点的值。

**2. 算法步骤**  
```java
public List<Integer> rightSideView(TreeNode root) {
    List<Integer> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> q = new LinkedList<>();
    q.offer(root);
    
    while (!q.isEmpty()) {
        int size = q.size(); // 当前层节点数
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            // 每层最后一个节点加入结果
            if (i == size - 1) res.add(node.val);
            if (node.left != null) q.offer(node.left);
            if (node.right != null) q.offer(node.right);
        }
    }
    return res;
}
```

**3. 关键点解析**  
- **队列作用**：`Queue<TreeNode>` 存储待处理节点，保证FIFO顺序。  
- **层级控制**：通过`size = q.size()`固定当前层节点数，避免跨层混淆。  
- **右视图提取**：每层循环结束时`i == size-1`即为最右节点。  

**4. 复杂度分析**  
- **时间复杂度**：O(n)，每个节点仅访问一次。  
- **空间复杂度**：O(n)，队列最大存储层宽（最坏情况为完全二叉树底层）。  

**5. 扩展思考**  
- 若求左视图？将`i == size-1`改为`i == 0`。  
- 若树为空？提前返回空列表（代码已处理）。  

**示例场景**  
输入树：  
```
    1
   / \
  2   3
     / \
    4   5
```
层序遍历：`[1,2,3,4,5]` → 右视图：`[1,3,5]`  

**总结**：通过队列模拟层级遍历，结合每层节点计数精准定位右视图，代码简洁且覆盖边界条件。'),
