### 参考答案：Go高并发场景下的数据安全与资源管理  

**1. 为什么用goroutine+channel而非传统锁？**  
Go采用CSP（通信顺序进程）模型，通过channel传递数据而非共享内存，避免竞态条件。例如车联网场景中，车辆实时数据流需多协程并行处理：  
```go
// 数据收集协程
go func() {
    for {
        data := collectVehicleData() // 模拟采集
        dataChan <- data             // 通过channel传递
    }
}()

// 处理协程池
for i := 0; i < 10; i++ {
    go func(id int) {
        for data := range dataChan {
            process(data) // 无锁处理
        }
    }(i)
}
```  
**2. 如何防止goroutine泄漏？**  
- **为什么**：未正确退出的协程会占用内存，导致服务崩溃。  
- **怎么做**：结合context超时控制与select机制：  
```go
func safeProcess(ctx context.Context, dataChan <-chan []byte) {
    for {
        select {
        case d, ok := <-dataChan:
            if !ok { return } // channel关闭时退出
            process(d)
        case <-ctx.Done():
            return // 超时/取消时主动退出
        }
    }
}
```  

**3. 内存泄漏排查与优化**  
- **为什么**：Go的GC无法回收未引用的goroutine或channel。  
- **怎么做**：  
  - 使用`pprof`定位泄漏点（如`go tool pprof http://localhost:6060/debug/pprof/heap`）  
  - 批量处理数据减少临时对象分配：  
  ```go
  batch := make([]byte, 0, 1024) // 预分配缓冲区
  ```  

**4. 错误处理策略**  
- **为什么**：panic会导致协程崩溃，影响整个服务。  
- **怎么做**：用defer+recover捕获异常，并记录日志：  
```go
defer func() {
    if r := recover(); r != nil {
        log.Printf("panic recovered: %v", r)
    }
}()
```  

**架构示例**：  
```
Client -> API Gateway -> Data Collector -> [Channel] -> Worker Pool -> MySQL  
|-> 每100条数据批量写入，减少DB压力  
|-> 使用sync.Pool复用对象，降低GC频率  
```  

**总结**：通过channel解耦、context控制生命周期、批量处理优化性能，可保障车联网场景下的高并发稳定性。'),
