### 参考答案：时间跨度查询的系统设计  

**1. 数据分区与索引优化**  
- **为什么**：大时间跨度查询（如1年）若直接扫全表，会导致索引失效、性能骤降。例如，`WHERE create_time BETWEEN ''2023-01-01'' AND ''2024-01-01''` 在单表中可能触发全表扫描。  
- **怎么做**：  
  - **按时间维度分区**：将数据按月/年分区（如MySQL `PARTITION BY RANGE (YEAR(create_time))`），查询时自动裁剪无关分区。  
  - **复合索引**：对 `create_time` 和业务字段（如 `user_id`）建联合索引，加速范围查询。  

**2. 多级缓存策略**  
- **为什么**：频繁查询相同时间范围的数据（如“近1小时订单”）会重复压库，需缓存减少数据库负载。  
- **怎么做**：  
  - **分层缓存**：  
    ```  
    短期查询（≤1天）→ Redis缓存（TTL=5分钟）  
    长期查询（>1天）→ 本地缓存（Caffeine）+ Redis（TTL=1天）  
    ```  
  - **防穿透**：对无效时间范围（如未来时间）用布隆过滤器拦截。  

**3. 冷热数据分离**  
- **为什么**：历史数据（如1年前）访问率低，但占用高性能存储资源（如SSD）。  
- **怎么做**：  
  - **热数据**：近3个月数据存MySQL（SSD），保障低延迟。  
  - **冷数据**：更旧数据迁移至HBase/对象存储（如S3），通过定时任务（如Flink）异步同步。  

**4. 查询路由层**  
- **为什么**：不同时间范围的数据分布在不同存储层，需智能路由避免无效查询。  
- **怎么做**：  
  - **路由逻辑**：  
    ```java  
    if (endTime - startTime <= 3个月) {  
        queryMySQL();  
    } else {  
        queryHBase();  
    }  
    ```  
  - **中间件**：使用ShardingSphere根据时间参数自动路由到对应数据源。  

**架构示意**：  
```  
Client -> API Gateway -> Query Router  
       |-> MySQL (Hot, 近3月)  
       |-> HBase (Cold, 历史数据)  
       |-> Redis (缓存层)  
```  

**总结**：通过分区+缓存+冷热分离+路由，兼顾查询性能与存储成本。例如，携程订单查询中，近1周数据走MySQL，1年以上数据走HBase，缓存命中率提升60%。'),
  ('other-539', '

### 参考答案

**1. 冷热分离的必要性**  
**为什么**：随着数据量增长，全量查询会拖慢响应速度并浪费资源。例如订单系统中，90%的请求集中在近3个月数据，而历史数据访问频率极低。若全量存储在高性能存储（如SSD/MySQL），会导致成本飙升且查询效率低下。  
**怎么做**：通过分层存储策略，将高频访问的“热数据”保留在低延迟存储层（如Redis/MySQL），低频的“冷数据”迁移至低成本存储（如HBase/OSS）。  

---

**2. 实现方案**  
**为什么**：需兼顾查询效率与成本，同时保证数据一致性。  
**怎么做**：  
- **数据分层存储**  
  热数据存储在MySQL分库分表（按时间分片），冷数据归档至HBase或对象存储。例如：  
  ```sql
  -- MySQL分区表示例（按月分区）
  CREATE TABLE orders (id BIGINT, create_time DATETIME) 
  PARTITION BY RANGE (YEAR(create_time)) (
    PARTITION p2023 VALUES LESS THAN (2024),
    PARTITION p2024 VALUES LESS THAN (2025)
  );
  ```  
- **动态迁移策略**  
  通过定时任务（如Quartz）或触发器，将超过阈值的冷数据异步迁移至冷存储。例如：  
  ```java
  // 伪代码：每日凌晨迁移3个月前数据
  @Scheduled(cron = "0 0 2 * * ?")
  public void migrateColdData() {
      List<Order> coldData = orderService.findByCreateTimeBefore(3 months);
      hbaseService.batchWrite(coldData);
      orderService.deleteBatch(coldData);
  }
  ```  
- **查询路由优化**  
  接口层根据时间参数动态路由到热/冷存储：  
  ```java
  public List<Order> queryOrders(Date start, Date end) {
      if (isHotData(start, end)) {
          return mysqlService.query(start, end);
      } else {
          return hbaseService.query(start, end);
      }
  }
  ```  

---

**3. 实际场景与监控**  
**为什么**：需避免冷热数据边界模糊导致查询失败。  
**怎么做**：  
- **动态阈值调整**：基于业务指标（如QPS、访问频率）自动调整冷热分界线。  
- **监控告警**：通过Prometheus监控冷热存储的延迟和容量，异常时触发告警。  

---

**架构示意**  
```
Client -> API Gateway -> [路由层] 
                          ├-> 热数据: MySQL (SSD) | Redis缓存
                          └-> 冷数据: HBase/OSS (归档存储)
```  
**总结**：冷热分离通过分层存储和智能路由，在保障核心业务性能的同时降低60%+存储成本，是大规模系统必备方案。'),
